'use strict';
const examples={link:{input:'https://somewhere.nice/a-place-worth-keeping',mark:'↗',type:'LINK + YOUR NOTE',title:'That little place for the weekend.'},note:{input:'Maybe the best ideas just need a place to stay.',mark:'Aa',type:'A THOUGHT, KEPT',title:'An idea before it disappears.'},image:{input:'A screenshot from your camera roll',mark:'▧',type:'IMAGE + SEARCHABLE TEXT · PLANNED',title:'The details you meant to remember.'}};
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{const e=examples[b.dataset.example];for(const key of ['input','mark','type','title'])document.getElementById('example-'+key).textContent=e[key];document.querySelectorAll('[data-example]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));
const greetings=[{file:'cozy-no-rush-v2.png',text:'no rush, really.'},{file:'cozy-thoughts-v2.png',text:'your thoughts can stay.'},{file:'cozy-room-v2.png',text:'room for one more.'}];let greeting=Math.floor(Math.random()*greetings.length);const message=document.getElementById('cozy-message'),lettering=document.getElementById('cozy-lettering');function showGreeting(){const g=greetings[greeting];lettering.alt=g.text;lettering.src='assets/'+g.file;message.setAttribute('aria-label',g.text+' Show another welcome message.')}lettering.onload=()=>message.hidden=false;lettering.onerror=()=>message.hidden=true;message.addEventListener('click',()=>{greeting=(greeting+1)%greetings.length;showGreeting()});showGreeting();
